PREPARE s13(bigint,text,text,text) AS INSERT INTO articles (id, slug, author_id, title, description, body) SELECT n.id, trim(both '-' from lower(regexp_replace($2, '[^A-Za-z0-9]+', '-', 'g'))) || '-' || n.id, $1, $2, $3, $4 FROM (SELECT nextval(pg_get_serial_sequence('articles', 'id')) AS id) n;
PREPARE s14(text[]) AS INSERT INTO tags (name) SELECT x.name FROM (SELECT DISTINCT unnest($1::text[]) AS name) x WHERE NOT EXISTS (SELECT 1 FROM tags t WHERE t.name = x.name) ORDER BY 1 ON CONFLICT (name) DO NOTHING;
PREPARE s15(text[]) AS INSERT INTO article_tags (article_id, tag_id) SELECT currval(pg_get_serial_sequence('articles', 'id')), t.id FROM tags t WHERE t.name = ANY($1::text[]);
PREPARE s16(bigint) AS SELECT a.slug, a.title, a.description, a.body, a.created_at, a.updated_at, array_to_json(ARRAY(SELECT (SELECT t.name FROM tags t WHERE t.id = at.tag_id) FROM article_tags at WHERE at.article_id = a.id ORDER BY 1))::text, (SELECT count(*) FROM favorites f WHERE f.article_id = a.id), ($1 <> 0 AND EXISTS (SELECT 1 FROM favorites f WHERE f.article_id = a.id AND f.user_id = $1)), u.username, u.bio, u.image, ($1 <> 0 AND EXISTS (SELECT 1 FROM follows fo WHERE fo.follower_id = $1 AND fo.followee_id = a.author_id)) FROM articles a JOIN users u ON u.id = a.author_id WHERE a.id = (SELECT currval(pg_get_serial_sequence('articles', 'id')));
